\label{5.1}
A function $f:\mathbb{Z}_+\times \mathbb{Z}\longrightarrow \mathbb{C}$ is
said to be {\em expandable} if:\begin{enumerate}
\item the Fourier transform $\hat{f_0}$ of the function $f_0:\mathbb{Z}_+\longrightarrow\mathbb{C}$,  given by
\eqref{rest}, satisfies the estimate
\begin{equation}
\label{esti}
\limsup_{n\rightarrow\infty}(|\hat{f_0}(n)|n!)^{1/n}<\sqrt{2};
\end{equation}
\item the function $f$ admits the representation
$$ f(x,y)=\sum_{n\in\mathbb{Z}_+}\hat{f_0}(n)\zeta_n(x,y),\quad (x,y)\in\mathbb{Z}_+\times\mathbb{Z}.$$
\end{enumerate}

